Q: Scanlines gets wrong pixel colors A: <p>I tried your code, and your image, and it &quot;almost works&quot; for me.</p>
<p>So my guess is that your image is actually a 32-bit bitmap, and not a 24-bit bitmap, as your code expects. (The actual pixel format of your bitmap was obviously lost when you uploaded it as a PNG. And then I saved it as a 24-bit bitmap.)</p>
<p>You need to check the <code>PixelFormat</code> of your bitmap. Your code will only work if this is <code>pf24bit</code>.</p>
<p>Also, your code only &quot;almost&quot; works, so there's something more going on. Maybe the selection rectangle itself is affecting the average you compute? This is just one of the reasons I'd not use a <code>TImage</code> for this, as I detail further down.</p>
<p>Furthermore, you don't need to create your own pixel records. Just use <code>TRGBTriple</code> or <code>TRGBQuad</code>, depending on the pixel format.</p>
<p>Here's some sample code:</p>
<pre class="lang-pascal prettyprint-override"><code>function GetAverageColor(ABitmap: TBitmap): TColor;
begin

  {$POINTERMATH ON}

  var r: Double := 0.0;
  var g: Double := 0.0;
  var b: Double := 0.0;

  case ABitmap.PixelFormat of
    pf24bit:
      begin

        for var y := 0 to ABitmap.Height - 1 do
        begin
          const SL: PRGBTriple = ABitmap.ScanLine[y];
          for var x := 0 to ABitmap.Width - 1 do
          begin
            r := r + SL[x].rgbtRed / 255;
            g := g + SL[x].rgbtGreen / 255;
            b := b + SL[x].rgbtBlue / 255;
          end;
        end;

      end;
    pf32bit:
      begin

        for var y := 0 to ABitmap.Height - 1 do
        begin
          const SL: PRGBQuad = ABitmap.ScanLine[y];
          for var x := 0 to ABitmap.Width - 1 do
          begin
            r := r + SL[x].rgbRed / 255;
            g := g + SL[x].rgbGreen / 255;
            b := b + SL[x].rgbBlue / 255;
          end;
        end;

      end;
  else
    raise Exception.Create('Unsupported pixel format.');
  end;

  r := r / (ABitmap.Width * ABitmap.Height);
  g := g / (ABitmap.Width * ABitmap.Height);
  b := b / (ABitmap.Width * ABitmap.Height);

  Result := RGB(
    Round(255 * r),
    Round(255 * g),
    Round(255 * b)
  );

end;
</code></pre>
<p>But as I said, I would not use a <code>TImage</code> for this, but a custom control (or just a plain <code>TForm</code>) and my own off-screen <code>TBitmap</code> (which I set to <code>pf24bit</code>).</p>
<p>Also, I'd make sure to double-buffer and handle the <code>WM_ERASEBKGND</code> message to remove flickering.</p>
<h1>Complete example</h1>
<p>Here's how I'd do this:</p>
<pre class="lang-pascal prettyprint-override"><code>unit Unit1;

interface

uses
  Winapi.Windows, Winapi.Messages, System.SysUtils, System.Variants, System.Classes, Vcl.Graphics,
  Vcl.Controls, Vcl.Forms, Vcl.Dialogs;

type
  TForm1 = class(TForm)
    procedure FormCreate(Sender: TObject);
    procedure FormPaint(Sender: TObject);
    procedure FormMouseDown(Sender: TObject; Button: TMouseButton;
      Shift: TShiftState; X, Y: Integer);
    procedure FormMouseMove(Sender: TObject; Shift: TShiftState; X, Y: Integer);
    procedure FormMouseUp(Sender: TObject; Button: TMouseButton;
      Shift: TShiftState; X, Y: Integer);
    procedure FormKeyDown(Sender: TObject; var Key: Word; Shift: TShiftState);
  private
    FBitmap: TBitmap;
    FStart,
    FEnd: TPoint;
    FDown: Boolean;
    procedure DoFillRect(const ARect: TRect; AColor: TColor);
  public
    procedure WMEraseBkgnd(var Message: TWMEraseBkgnd); message WM_ERASEBKGND;
  end;

var
  Form1: TForm1;

implementation

{$R *.dfm}

function GetAverageColor(ABitmap: TBitmap; const ARect: TRect): TColor;
begin

  {$POINTERMATH ON}

  var r: Double := 0.0;
  var g: Double := 0.0;
  var b: Double := 0.0;

  Assert(Assigned(ABitmap));
  Assert(Rect(0, 0, ABitmap.Width - 1, ABitmap.Height - 1).Contains(ARect));
  Assert(not ARect.IsEmpty);

  case ABitmap.PixelFormat of
    pf24bit:
      begin

        for var y := ARect.Top to ARect.Bottom - 1 do
        begin
          const SL: PRGBTriple = ABitmap.ScanLine[y];
          for var x := ARect.Left to ARect.Right - 1 do
          begin
            r := r + SL[x].rgbtRed / 255;
            g := g + SL[x].rgbtGreen / 255;
            b := b + SL[x].rgbtBlue / 255;
          end;
        end;

      end;
    pf32bit:
      begin

        for var y := ARect.Top to ARect.Bottom - 1 do
        begin
          const SL: PRGBQuad = ABitmap.ScanLine[y];
          for var x := ARect.Left to ARect.Right - 1 do
          begin
            r := r + SL[x].rgbBlue / 255;
            g := g + SL[x].rgbGreen / 255;
            b := b + SL[x].rgbBlue / 255;
          end;
        end;

      end;
  else
    raise Exception.Create('Unsupported pixel format.');
  end;

  const A = ARect.Width * ARect.Height;
  r := r / A;
  g := g / A;
  b := b / A;

  Result := RGB(
    Round(255 * r),
    Round(255 * g),
    Round(255 * b)
  );

end;

procedure TForm1.DoFillRect(const ARect: TRect; AColor: TColor);
begin

  if FBitmap = nil then
    Exit;

  FBitmap.Canvas.Brush.Color := AColor;
  FBitmap.Canvas.Brush.Style := bsSolid;
  FBitmap.Canvas.FillRect(ARect);

end;

procedure TForm1.FormCreate(Sender: TObject);
begin

  DoubleBuffered := True;
  Cursor := crCross;

  FBitmap := TBitmap.Create;
  FBitmap.LoadFromFile('D:\test.bmp');
  FBitmap.PixelFormat := pf24bit;

end;

procedure TForm1.FormKeyDown(Sender: TObject; var Key: Word;
  Shift: TShiftState);
begin
  case Key of
    VK_ESCAPE:
      begin
        FStart := TPoint.Zero;
        FEnd := TPoint.Zero;
        FDown := False;
        ClipCursor(nil);
        Invalidate;
      end;
  end;
end;

procedure TForm1.FormMouseDown(Sender: TObject; Button: TMouseButton;
  Shift: TShiftState; X, Y: Integer);
begin
  if Button = TMouseButton.mbLeft then
  begin
    FDown := True;
    FStart := Point(X, Y);
    var R := ClientToScreen(Rect(0, 0, FBitmap.Width - 1, FBitmap.Height - 1));
    ClipCursor(@R);
  end;
end;

procedure TForm1.FormMouseMove(Sender: TObject; Shift: TShiftState; X,
  Y: Integer);
begin

  if FDown and (csLButtonDown in ControlState) then
  begin
    FEnd := Point(X, Y);
    Invalidate;
  end;

end;

procedure TForm1.FormMouseUp(Sender: TObject; Button: TMouseButton;
  Shift: TShiftState; X, Y: Integer);
begin

  ClipCursor(nil);

  const LWasDown = FDown;
  FDown := False;

  var R := Rect(FStart, FEnd);
  R.NormalizeRect;

  FStart := TPoint.Zero;
  FEnd := TPoint.Zero;

  if LWasDown and (Button = TMouseButton.mbLeft) then
  begin

    if not R.IsEmpty then
      DoFillRect(R, GetAverageColor(FBitmap, R));

    Invalidate;

  end;

end;

procedure TForm1.FormPaint(Sender: TObject);
begin

  Canvas.Brush.Color := Self.Color;
  Canvas.Brush.Style := bsSolid;
  Canvas.FillRect(ClientRect);

  if Assigned(FBitmap) then
    Canvas.Draw(0, 0, FBitmap);

  if csLButtonDown in ControlState then
  begin
    var R := Rect(FStart, FEnd);
    R.NormalizeRect;
    Canvas.Pen.Mode := pmNot;
    Canvas.Brush.Style := bsClear;
    Canvas.Rectangle(R);
    Canvas.Pen.Mode := pmBlack;
  end;

end;

procedure TForm1.WMEraseBkgnd(var Message: TWMEraseBkgnd);
begin
  Message.Result := 1;
end;

end.
</code></pre>
<p>To test this:</p>
<ul>
<li>Make sure that you can make rectangles in any direction (for instance, from bottom-right to top-left).</li>
<li>Make sure you can abort the operation by pressing Escape.</li>
<li>Make sure nothing bad happens if your app loses focus while dragging (e.g., Win+L).</li>
<li>Make sure you never access pixels not present in the bitmap (when working with scanlines).</li>
</ul>
<p>Example:</p>
<p><a href="https://privat.rejbrand.se/avgbitmapcolor.mp4" rel="nofollow noreferrer">https://privat.rejbrand.se/avgbitmapcolor.mp4</a></p>
<h1>Your updated code for programmatically drawing squares</h1>
<p>Your new code</p>
<pre class="lang-pascal prettyprint-override"><code>    procedure TForm1.BtnDrawMatrixClick(Sender: TObject);
    var
        X, Y: Integer;
        R: TRect;
    begin
        for Y := 1 to 15 do
            for X := 1 to 20 do
            begin
                R.TopLeft := Point(50 * X, 50 * Y);
                R.BottomRight := Point(50 * X + 40, 50 * Y + 40);
                DrawAverageColor(R);
            end;
    end;
</code></pre>
<p>will not work because you access, for instance, <code>Point(1000, 750)</code> which does not exist in your 640×490 bitmap image.</p>
<p>And your area is computed incorrectly:</p>
<pre class="lang-pascal prettyprint-override"><code>Area := Abs((aRect.Top - aRect.Bottom + 1) * (aRect.Left - aRect.Right + 1));
</code></pre>
<p>If <code>ARect = Rect(50, 50, 90, 90)</code> then you accumulate <code>R</code>, <code>G</code>, and <code>B</code> 1600 times, but your <code>Area</code> becomes <code>1521</code>.</p>
<p>So for your reddish region in the top-left, you get <code>R = 406211</code> (say), so that <code>R / Area</code> becomes about <code>267</code>, which is more than <code>255</code>. So if you <code>and</code> it with <code>$FF</code>, you get very little red (incorrect).</p>
<p>If, on the other hand, <code>Area = 1600</code>, you get <code>R / Area</code> about <code>254</code>, which is OK, so and with <code>$FF</code> you get <code>254</code>, which is very much red (correct).</p>

Q: Background color problems A: <p>&lt;!DOCTYPE html&gt;</p>
<p>&lt;html&gt;</p>
<p>&lt;body style=&quot;margin:0; overflow:hidden; background: #000; font-family: Arial, sans-serif;&quot;&gt;</p>
<p>&lt;!-- Интерфейс --&gt;</p>
<p>&lt;div id=&quot;ui&quot; style=&quot;position:absolute; color:white; padding:20px; pointer-events:none;&quot;&gt;</p>
<pre><code>\&lt;h2 id=&quot;locName&quot;\&gt;Локация: СССР\&lt;/h2\&gt;

\&lt;div id=&quot;scoreDisplay&quot;\&gt;Счет: 0\&lt;/div\&gt;
</code></pre>
<p>&lt;/div&gt;</p>
<p>&lt;!-- Чит-меню --&gt;</p>
<p>&lt;button onclick=&quot;toggleMenu()&quot; style=&quot;position:absolute; top:10px; right:10px; z-index:100; cursor:pointer;&quot;&gt;⚙️ НАСТРОЙКИ (ЧИТЫ)&lt;/button&gt;</p>
<p>&lt;div id=&quot;settingsMenu&quot; style=&quot;position:absolute; top:50px; right:10px; background:rgba(0,0,0,0.9); color:#0f0; padding:15px; display:none; border:2px solid #0f0; z-index:100;&quot;&gt;</p>
<pre><code>\&lt;h3 style=&quot;margin-top:0&quot;\&gt;REVOLUTION CHEATS\&lt;/h3\&gt;

\&lt;label style=&quot;display:block; margin-bottom:10px;&quot;\&gt;\&lt;input type=&quot;checkbox&quot; id=&quot;flyMode&quot;\&gt; 🚀 ПОЛЕТ (СКВОЗЬ СТЕНЫ)\&lt;/label\&gt;

\&lt;label style=&quot;display:block; margin-bottom:10px;&quot;\&gt;\&lt;input type=&quot;checkbox&quot; id=&quot;godMode&quot;\&gt; 🛡️ БЕССМЕРТИЕ\&lt;/label\&gt;

\&lt;label style=&quot;display:block; margin-bottom:10px;&quot;\&gt;\&lt;input type=&quot;checkbox&quot; id=&quot;speedMode&quot;\&gt; ⚡ СУПЕР-СКОРОСТЬ\&lt;/label\&gt;

\&lt;button onclick=&quot;toggleMenu()&quot; style=&quot;width:100%; cursor:pointer;&quot;\&gt;ЗАКРЫТЬ\&lt;/button\&gt;
</code></pre>
<p>&lt;/div&gt;</p>
<p>&lt;canvas id=&quot;game&quot;&gt;&lt;/canvas&gt;</p>
<p>&lt;script&gt;</p>
<p>const canvas = document.getElementById('game');</p>
<p>const ctx = canvas.getContext('2d');</p>
<p>canvas.width = window.innerWidth;</p>
<p>canvas.height = window.innerHeight;</p>
<p>let p = { x: 100, y: 300, s: 30, v: 5 };</p>
<p>let score = 0;</p>
<p>let currentMap = 'USSR';</p>
<p>let bullets = [];</p>
<p>let enemies = [];</p>
<p>let environment = [];</p>
<p>let keys = {};</p>
<p>let cheats = { fly: false, god: false };</p>
<p>// Генерация руин</p>
<p>for(let i=0; i&lt;20; i++) {</p>
<pre><code>environment.push({ x: Math.random()\*canvas.width, y: Math.random()\*canvas.height, w: 40+Math.random()\*60, h: 60+Math.random()\*100 });
</code></pre>
<p>}</p>
<p>window.onkeydown = e =&gt; keys[e.key] = true;</p>
<p>window.onkeyup = e =&gt; keys[e.key] = false;</p>
<p>document.getElementById('flyMode').onchange = e =&gt; cheats.fly = e.target.checked;</p>
<p>document.getElementById('godMode').onchange = e =&gt; cheats.god = e.target.checked;</p>
<p>document.getElementById('speedMode').onchange = e =&gt; p.v = e.target.checked ? 15 : 5;</p>
<p>function toggleMenu() {</p>
<pre><code>const m = document.getElementById('settingsMenu');

m.style.display = m.style.display === 'none' ? 'block' : 'none';
</code></pre>
<p>}</p>
<p>window.onmousedown = e =&gt; {</p>
<pre><code>const angle = Math.atan2(e.clientY - p.y, e.clientX - p.x);

bullets.push({ x: p.x + 15, y: p.y + 15, vx: Math.cos(angle)\*10, vy: Math.sin(angle)\*10 });
</code></pre>
<p>};</p>
<p>function loop() {</p>
<pre><code>// 1. Движение

if(keys\['ArrowUp'\] || keys\['w'\]) p.y -= p.v;

if(keys\['ArrowDown'\] || keys\['s'\]) p.y += p.v;

if(keys\['ArrowLeft'\] || keys\['a'\]) p.x -= p.v;

if(keys\['ArrowRight'\] || keys\['d'\]) p.x += p.v;

if(!cheats.fly) {

    p.x = Math.max(0, Math.min(canvas.width-p.s, p.x));

    p.y = Math.max(0, Math.min(canvas.height-p.s, p.y));

}

// 2. Логика карт

ctx.fillStyle = currentMap === 'USSR' ? '#2c3e50' : '#1a1a1a';

ctx.fillRect(0, 0, canvas.width, canvas.height);

// Рисуем заброшенные здания

ctx.fillStyle = currentMap === 'USSR' ? '#7f8c8d' : '#34495e';

environment.forEach(ruin =\&gt; ctx.fillRect(ruin.x, ruin.y, ruin.w, ruin.h));

// Портал в Германию

if(currentMap === 'USSR') {

    ctx.fillStyle = '#e74c3c';

    ctx.fillRect(canvas.width - 60, canvas.height/2 - 50, 60, 100);

    ctx.fillStyle = 'white';

    ctx.fillText(&quot;В БЕРЛИН&quot;, canvas.width - 80, canvas.height/2 - 60);

    if(p.x \&gt; canvas.width - 60) { currentMap = 'GERMANY'; p.x = 50; document.getElementById('locName').innerText = &quot;Локация: ГЕРМАНИЯ&quot;; }

}

// 3. Враги (только в Германии)

if(currentMap === 'GERMANY') {

    if(Math.random() \&lt; 0.02) enemies.push({x: canvas.width, y: Math.random()\*canvas.height, s: 30});



    enemies.forEach((en, i) =\&gt; {

        let dist = Math.hypot(p.x - en.x, p.y - en.y);

        en.x += (p.x - en.x)/dist \* 2;

        en.y += (p.y - en.y)/dist \* 2;



        ctx.fillStyle = '#555'; // Мундир

        ctx.fillRect(en.x, en.y, en.s, en.s);

        ctx.fillStyle = 'red';

        ctx.fillRect(en.x + 5, en.y, 20, 5); // Деталь формы

        if(dist \&lt; 30 &amp;&amp; !cheats.god) location.reload();

    });

}

// 4. Пули

bullets.forEach((b, bi) =\&gt; {

    b.x += b.vx; b.y += b.vy;

    ctx.fillStyle = '#f1c40f';

    ctx.beginPath(); ctx.arc(b.x, b.y, 5, 0, 7); ctx.fill();



    enemies.forEach((en, ei) =\&gt; {

        if(Math.hypot(b.x - en.x, b.y - en.y) \&lt; 20) {

            enemies.splice(ei, 1);

            bullets.splice(bi, 1);

            score += 10;

            document.getElementById('scoreDisplay').innerText = &quot;Счет: &quot; + score;

        }

    });

});

// 5. Игрок

ctx.fillStyle = '#3498db';

ctx.fillRect(p.x, p.y, p.s, p.s);

if(cheats.god) { ctx.strokeStyle = 'gold'; ctx.lineWidth = 3; ctx.strokeRect(p.x-2, p.y-2, p.s+4, p.s+4); }

requestAnimationFrame(loop);
</code></pre>
<p>}</p>
<p>loop();</p>
<p>&lt;/script&gt;</p>
<p>&lt;/body&gt;</p>
<p>&lt;/html&gt;</p>

Q: How to align form labels in SwiftUI form on macOS? A: <p>One way to get it working is to define a custom <code>LabeledContentStyle</code>:</p>
<pre class="lang-swift prettyprint-override"><code>struct VerticallyCenteredLabelStyle: LabeledContentStyle {
    func makeBody(configuration: Configuration) -&gt; some View {
        HStack {
            configuration.label
            configuration.content
        }
    }
}
</code></pre>
<p>For convenience, an extension can also be defined:</p>
<pre class="lang-swift prettyprint-override"><code>extension LabeledContentStyle where Self == VerticallyCenteredLabelStyle {
    static var verticallyCenteredLabel: Self { Self() }
}
</code></pre>
<p>Applying it to your example:</p>
<pre class="lang-swift prettyprint-override"><code>Form {
    ColorPicker(&quot;Color&quot;, selection: $color)
        .labeledContentStyle(.verticallyCenteredLabel)
}
</code></pre>
